            "properties": {
              "pct_col1": {
                "type": "number"
              },
              "pct_col2": {
                "type": "number"
              },
              "n_total": {
                "type": "integer"
              },
              "decimals": {
                "type": "integer",
                "description": "The COARSEST printed precision among the percentages given. One window covers both columns, so the finest precision present would shrink it for both. No default -- the wrong one accuses."
              },
              "value_type": {
                "type": "string"
              },
              "reported_chi2": {
                "type": "number"
              },
              "chi2_tolerance": {
                "type": "number"
